import { createApp } from "./app.js";
import { DATASET, PORT } from "./config.js";
import { db, seedLarge, seedSample } from "./store.js";

if (DATASET === "large") seedLarge();
else seedSample();

createApp().listen(PORT, () => {
  console.log(`library API listening on http://localhost:${PORT} (dataset: ${DATASET}, books: ${db.books.length})`);
});
